<script lang="ts">import { onMount } from 'svelte'; import { mergeEvents, validateSequence, type Event } from '$lib/reconnect/conflicts'; let events: Event[] = []; let message = 'No events restored.'; onMount(() => { if (new URLSearchParams(location.search).get('restore') === '1') { events = mergeEvents([{ seq: 1, type: 'room/created', payload: {} }], [{ seq: 2, type: 'player/joined', payload: {} }]); message = `Restored ${validateSequence(events).length} events; no conflicts.`; } });</script>
<main><section><h1>Reconnect and replay</h1><p>Clients validate sequence numbers and merge duplicate event streams.</p><a href="/reconnect/?restore=1" data-sveltekit-reload>Restore session</a><p role="status">{message}</p></section></main><style>:global(body){margin:0;background:#17251f;color:#f6efda;font-family:system-ui}main{padding:2rem;min-height:100vh}section{max-width:50rem;margin:10vh auto;padding:3rem;background:#f6efda;color:#20261f}a{display:inline-block;padding:1rem;background:#6d452d;color:#fff}</style>
